#!/usr/bin/env python3
"""Regenerate committed static pages after editing site.json or page copy."""
from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parents[1]
S=json.loads((ROOT/'site.json').read_text())
STAT='<span class="stat-properties">'+e(S['properties_touched'])+' properties touched</span>'
POD=e(S['podcast_line'])
HEADER='<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="site-header-inner"><p class="site-name"><a href="/">Nick Giulioni</a></p><nav class="site-nav" aria-label="Primary"><a href="/sell/">Sell</a><a href="/buy/">Buy</a><a href="/areas/">Areas</a><a href="/about/">About</a><a class="contact-link" href="/contact/">Request a consult</a></nav><a class="header-phone" href="'+S['phone_tel']+'">'+S['phone_display']+'</a></div></header>'
FOOTER='<footer class="site-footer"><p class="disclosure">Nick Giulioni is an Indiana real estate broker affiliated with T&amp;H Realty Services, 760 E. 52nd St, Indianapolis, IN 46205, 317-255-7767.</p><p class="housing"><img src="/assets/equal-housing.svg" width="28" height="28" alt="Equal Housing Opportunity"> Equal Housing Opportunity.</p><div class="footer-links"><a href="mailto:'+S['email']+'">'+S['email']+'</a><a href="'+S['phone_tel']+'">'+S['phone_display']+'</a><a href="/privacy/">Privacy</a><a href="https://www.linkedin.com/in/nickgiulioni">LinkedIn</a></div><p>© 2026 Nick Giulioni</p></footer>'
def form(source,review=False):
    fields=''
    for name,label,kind,auto,limit in [('name','Name','text','name',100),('email','Email','email','email',254),('phone','Phone','tel','tel',40),('location','Property address' if review else 'City or address','text','street-address',300)]:
        required=' required' if name!='location' or review else ''
        fields+=f'<label for="{source}-{name}">{label}<input id="{source}-{name}" name="{name}" type="{kind}" autocomplete="{auto}" maxlength="{limit}"{required}></label>'
    intents='<input type="hidden" name="intent" value="Sell or rent review">' if review else '<fieldset><legend>What can I help with?</legend>'+''.join(f'<label class="choice"><input type="radio" name="intent" value="{v}" required> {v}</label>' for v in ['Buy','Sell','Both','Sell or rent review','Not sure'])+'</fieldset>'
    return f'<form method="post" action="/api/consult" class="consult-form"><input type="hidden" name="source" value="{source}"><div class="form-grid">{fields}</div>{intents}<label for="{source}-message">Message (optional)<textarea id="{source}-message" name="message" rows="4" maxlength="2000"></textarea></label><label class="honeypot" aria-hidden="true">Company website<input name="company_website" type="text" tabindex="-1" autocomplete="off"></label><label class="choice consent"><input type="checkbox" name="consent" value="yes" required> <span>I agree that Nick Giulioni may contact me by call, email, or text about this request. Message and data rates may apply. Reply STOP to opt out. See the <a href="/privacy/">privacy policy</a>.</span></label><button class="btn btn-primary" type="submit">Request a consult</button></form>'
def slot(source):
    return '<section id="sell-or-rent" class="sell-or-rent"><p class="section-label">A decision before a listing</p><h2>Sell it or rent it?</h2><p>Tell me the address. I review a sell-versus-rent range and send it to you myself. This is not an instant appraisal.</p><div class="sell-or-rent__embed">'+form(source,True)+'</div></section>'
def section(title,text): return '<section class="editorial"><h2>'+title+'</h2><p>'+text+'</p></section>'
def cta(label='Request a consult'): return '<section class="closing-cta"><p>Let’s talk through your next move.</p><a class="btn btn-primary" href="/contact/">'+label+'</a></section>'
def cards():
    return '<div class="area-grid">'+''.join('<article class="area-card"><h2><a href="/areas/'+slug+'/">'+city+'</a></h2><p>'+desc+'</p></article>' for slug,city,desc in [('carmel','Carmel','Start here if established neighborhoods and time on the Monon are on your list.'),('westfield','Westfield','Compare new-build plans with existing homes, and put Grand Park on your map.'),('fishers','Fishers','Compare downtown routines with life closer to Fishers District.')])+'</div>'
def page(path,title,description,h1,body,card='home',noindex=False,hero=False):
    url='https://giulioni.com'+path
    head=f'<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>{e(title)}</title><meta name="description" content="{e(description)}">'
    if not noindex: head+=f'<link rel="canonical" href="{url}">'
    for prefix,key in [('property','og:title'),('property','og:description'),('property','og:url'),('property','og:type'),('property','og:image'),('property','og:image:width'),('property','og:image:height'),('property','og:image:alt'),('name','twitter:card'),('name','twitter:title'),('name','twitter:description'),('name','twitter:image'),('name','twitter:image:alt')]:
        value={'og:title':title,'og:description':description,'og:url':url,'og:type':'website','og:image':'https://giulioni.com/assets/og-'+card+'.png','og:image:width':'1200','og:image:height':'630','og:image:alt':'Nick Giulioni, Indiana real estate broker','twitter:card':'summary_large_image','twitter:title':title,'twitter:description':description,'twitter:image':'https://giulioni.com/assets/og-'+card+'.png','twitter:image:alt':'Nick Giulioni, Indiana real estate broker'}[key]
        head+=f'<meta {prefix}="{key}" content="{e(value)}">'
    head+='<meta name="theme-color" content="#16211c"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="stylesheet" href="/styles.css">'
    for font in ['instrument-sans-latin-wght','newsreader-latin-normal']: head+=f'<link rel="preload" href="/assets/fonts/{font}.woff2" as="font" type="font/woff2" crossorigin>'
    if noindex: head+='<meta name="robots" content="noindex">'
    if path in ['/', '/about/']:
        schema={'@context':'https://schema.org','@type':'RealEstateAgent','name':'Nick Giulioni','url':'https://giulioni.com/','email':S['email'],'telephone':'+1-463-223-9952','image':'https://giulioni.com/assets/portrait-nick-636.jpg','areaServed':[{'@type':'City','name':x+', Indiana'} for x in ['Carmel','Westfield','Fishers']],'worksFor':{'@type':'RealEstateAgent','name':'T&H Realty Services','telephone':'317-255-7767','address':{'@type':'PostalAddress','streetAddress':'760 E. 52nd St','addressLocality':'Indianapolis','addressRegion':'IN','postalCode':'46205'}}}
        head+='<script type="application/ld+json">'+json.dumps(schema)+'</script>'
    heading='' if hero else '<header class="page-header"><p class="page-kicker">Central Indiana real estate</p><h1 class="page-title">'+e(h1)+'</h1></header>'
    dest=ROOT/('404.html' if path=='/404.html' else path.lstrip('/')+'index.html'); dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text('<!doctype html>\n<html lang="en"><head>'+head+'</head><body>'+HEADER+'<main id="main" class="page-main">'+heading+body+'</main>'+FOOTER+'</body></html>\n')

PORTRAIT='<figure class="portrait">\n      <picture>\n        <source type="image/webp" srcset="/assets/portrait-nick-160.webp 160w, /assets/portrait-nick-200.webp 200w, /assets/portrait-nick-320.webp 320w, /assets/portrait-nick-348.webp 348w, /assets/portrait-nick-400.webp 400w, /assets/portrait-nick-636.webp 636w" sizes="(max-width: 520px) 160px, (max-width: 900px) 200px, (max-width: 1240px) calc(30vw - 24px), 348px">\n        <img src="/assets/portrait-nick-348.jpg" srcset="/assets/portrait-nick-160.jpg 160w, /assets/portrait-nick-200.jpg 200w, /assets/portrait-nick-320.jpg 320w, /assets/portrait-nick-348.jpg 348w, /assets/portrait-nick-400.jpg 400w, /assets/portrait-nick-636.jpg 636w" sizes="(max-width: 520px) 160px, (max-width: 900px) 200px, (max-width: 1240px) calc(30vw - 24px), 348px" width="636" height="954" fetchpriority="high" alt="Nick Giulioni seated and looking out a window.">\n      </picture>\n    </figure>'
MEDIA='<article class="media-entry">\n      <div class="media-meta"><h2 class="show-name">Roots Realty Co.</h2></div>\n      <div class="entry-detail">\n        <p class="episode-title"><a href="https://www.rootsrealty.co/podcast/nick-giulioni-real-estate">You WON\'T BELIEVE Nick Giulioni\'s Journey from Tech to Real Estate</a></p>\n        <p>Nick talks about moving from technology into Indiana real estate and building operating businesses.</p>\n      </div>\n    </article>\n<article class="media-entry">\n      <div class="media-meta"><h2 class="show-name">The Leverage Podcast</h2></div>\n      <div class="entry-detail">\n        <p class="episode-title"><a href="https://www.youtube.com/watch?v=_A2HrOjWe50">The Leverage Podcast - Nick Giulioni</a></p>\n        <p>Nick talks about his work, investments, and operating background.</p>\n      </div>\n    </article>\n<article class="media-entry">\n      <div class="media-meta"><h2 class="show-name">The Intrigue Podcast (formerly The Circle Investor Meetup &amp; Podcast)</h2></div>\n      <div class="entry-detail">\n        <p class="episode-title"><a href="https://www.youtube.com/watch?v=dv72SopKqeM">Episode 1 - Nick Giulioni: How To Go From Side Hustle To Real Business</a></p>\n        <p>Nick talks through the shift from a side hustle into an operating business.</p>\n      </div>\n    </article>\n<article class="media-entry">\n      <div class="media-meta"><h2 class="show-name">Going Long with Billy Keels</h2></div>\n      <div class="entry-detail">\n        <p class="episode-title"><a href="https://www.youtube.com/watch?v=B3gRQMjCng0">Convert I.T. Skills Into Long Distance Real Estate Investing Success - Nick Giulioni</a></p>\n        <p>Nick talks about applying an I.T. background to long-distance real-estate investing.</p>\n      </div>\n    </article>\n<article class="media-entry">\n      <div class="media-meta"><h2 class="show-name">Simple Quarters</h2></div>\n      <div class="entry-detail">\n        <p class="episode-title"><a href="https://www.simplequarters.com/podcasts/finding-deals-in-todays-real-estate-market">Finding Deals In Today\'s Real Estate Market</a></p>\n        <p>Nick and Brett Snodgrass discuss finding deals, seller conversations, due diligence, and building a team.</p>\n      </div>\n    </article>\n<article class="media-entry">\n      <div class="media-meta"><h2 class="show-name">Hacking Real Estate Podcast</h2></div>\n      <div class="entry-detail">\n        <p class="episode-title"><a href="https://www.hackingrealestatepodcast.com/episodes/104-nick-giulioni">Episode 4 Nick Giulioni</a></p>\n        <p>Nick talks about moving from tech work into real estate, remote operations, and wedding venues.</p>\n      </div>\n    </article>'
page('/', 'Nick Giulioni | Carmel, Westfield and Fishers real estate broker', 'Buyer and seller help in Carmel, Westfield and Fishers from an investor with renovation experience and T&H Realty Services broker.', '', '<section class="home-hero"><div class="hero-content"><p class="page-kicker">Indiana real estate broker, T&amp;H Realty Services</p><h1 class="hero-lede">Your next move. An agent who has been on the other side.</h1><p class="hero-targeting">Buy or sell in Carmel, Westfield, and Fishers with an investor who knows what a house needs. '+STAT+'.</p><p>'+POD+'</p><div class="hero-actions"><a class="btn btn-primary" href="/contact/">Request a consult</a><a class="hero-link" href="#sell-or-rent">See sell or rent</a></div></div>'+PORTRAIT+'</section>'+section('A practical eye for your next home', 'My background is in tech sales. I have been investing in Central Indiana since 2017. Years running renovation and new-build work taught me to look past finishes and ask what a property needs. I live in Carmel. Now I represent buyers and sellers in Carmel, Westfield, and Fishers, bringing that experience to the conversation.')+slot('sell-or-rent-home')+'<section class="editorial"><p class="section-label">Three places to start</p><h2>Find the town that fits your day.</h2>'+cards()+'</section><section class="numbers-row" aria-label="By the numbers"><p>'+STAT+'</p><p>Investing in Central Indiana since 2017</p><p>Lives in Carmel</p><p>'+POD+'</p></section>'+section('A conversation about Indiana real estate',POD+' <a href="/podcast/">Podcast and earlier media</a>.')+cta(),hero=True)
page('/sell/', 'Selling a home in Carmel, Westfield or Fishers | Nick Giulioni', 'A personal seller consult, preparation advice and a sell-versus-rent review for your Carmel, Westfield or Fishers home.', 'Thinking about selling in Carmel, Westfield, or Fishers?', '<p class="page-deck">Start with your timing, the condition of the home, and what you want to do next.</p><div class="hero-actions"><a class="btn btn-primary" href="/contact/">Request a seller consult</a><a class="hero-link" href="#sell-or-rent">Ask about sell or rent</a></div>'+section('A listing consult starts with listening','We talk through your goals, walk the property, and identify the questions that need answering before a listing. I respond personally, usually the same day.')+section('Selling is one option','Keeping a property means weighing rent, expenses, repair reserves, and the time you want to put into it. Selling means weighing preparation, timing, and what you would do with the proceeds. The numbers I share are not an appraisal.')+slot('sell-or-rent-sell')+section('Fix what matters','Years running renovation and new-build work help me ask useful questions about condition. We can separate work worth pricing before a listing from changes a buyer may prefer to make. An older home and a new build deserve different preparation conversations.')+section('A clear process, with me directly','I am newly licensed as a broker. I bring '+STAT+' from my investing and renovation experience, and I live in Carmel. We agree on priorities, review the pricing rationale together, and set a communication plan before moving forward.')+'<p class="mgmt-referral">If you would rather keep the property and have it managed, I can introduce you to <a href="https://threaltyinc.com/">T&amp;H</a>.</p>'+cta('Request a seller consult'),card='sell')
page('/buy/', 'Buying a home in Carmel, Westfield or Fishers | Nick Giulioni', 'Compare towns, home condition and new-build choices with a personal Hamilton County buyer consult from Nick Giulioni.', 'Buying in Hamilton County? Start with the right town.', section('Choose your everyday routine','Start with where you need to be, what you want nearby, and how much house you want to look after. Compare <a href="/areas/carmel/">Carmel</a>, <a href="/areas/westfield/">Westfield</a>, and <a href="/areas/fishers/">Fishers</a> before narrowing the home list.')+section('Look beyond the finishes','For an existing home, we can talk through condition, likely projects, and what to ask an inspector. For a new build, we can compare the base plan with options, timing, and the finished cost. My renovation background helps frame the questions; specialist inspections still matter.')+section('What a buyer consult covers','We discuss your budget, timing, location, and tolerance for projects. Then we agree on the next steps, including financing conversations and a plan for seeing homes. Live listing search comes later. For now, tell me what you are looking for.')+cta('Request a buyer consult'),card='buy')
page('/areas/', 'Carmel, Westfield and Fishers: where to live | Nick Giulioni', 'A practical starting point for choosing between Carmel, Westfield and Fishers, Indiana.', 'Carmel, Westfield, or Fishers?', '<p class="page-deck">Choose the daily routine first. Then choose the home.</p>'+cards()+section('Coming later','Zionsville and Noblesville guides are coming later. We can still talk through your location questions in a consult.')+cta(),card='areas')
page('/areas/carmel/', 'Living in Carmel, Indiana: real estate guide | Nick Giulioni', 'Living in Carmel, Indiana: compare the Arts and Design District, home choices and renovation tradeoffs with a local broker.', 'Living in Carmel, Indiana',
 section('Is Carmel the right fit?', 'Start your Carmel Indiana real estate search with the routine you want. If you picture coffee, galleries, and a walk through the Arts and Design District, spend time there before choosing a home. If privacy and a large yard matter more than being near that activity, look beyond the district and compare the actual lots.')+
 section('District living or room to change a home?', 'The city describes apartments and condos around the Arts and Design District. That can be a useful starting point if you want less outdoor upkeep. For any existing house you consider, weigh the floor plan and condition against the cost of changing them. If you prefer a new build, ask which finishes and site work are included rather than comparing the advertised starting price alone. <a href="https://www.carmel.in.gov/our-city/resident/arts-design-district">Source: City of Carmel district guide, checked November 18, 2026</a>.')+
 section('Make the drive part of your search', 'Before you narrow a Carmel home search to one neighborhood, drive from it to work and your regular errands. Try your normal departure time and your evening return. A home near a favorite destination still needs to work for the rest of your week.')+
 section('The Carmel Arts and Design District and the Monon', 'The Monon Greenway runs through the district, according to the city. Walk the route from a home you are considering to the places you would use, including crossings and the trip back. Being in Carmel is different from being a comfortable walk from the district. <a href="https://www.carmel.in.gov/our-city/resident/arts-design-district">Source: Carmel Arts and Design District guide, checked November 18, 2026</a>.')+
 section('Confirm the school boundary', 'For a Carmel address, consult <a href="https://www.ccs.k12.in.us/">Carmel Clay Schools’ official site</a> and confirm the applicable district and enrollment requirements before making a decision (checked November 18, 2026).')+
 section('Budget for the house behind the finishes', 'An updated kitchen does not answer questions about an older home’s systems or prior alterations. I can help you separate the cosmetic wish list from work that needs an inspection or a contractor’s estimate. For a new home, we can review the specification alongside your move-in budget.')+cta(),card='areas')
page('/areas/westfield/', 'Living in Westfield, Indiana: Grand Park and new builds | Nick Giulioni', 'Compare new-build and existing homes in Westfield, Indiana, with Grand Park, your commute and the full project cost in mind.', 'Living in Westfield, Indiana',
 section('Start with how you would use Westfield', 'Put Westfield on your list if choosing a floor plan and comparing a builder’s proposal with an existing home appeals to you. If Grand Park is part of your week, include it in your location search. If you need a home on a firm near-term date, keep completed homes in the comparison instead of relying on a proposed completion date.')+
 section('Compare the finished cost, not just the base plan', 'For a new build, request a written breakdown of the lot, options, allowances, and work due after closing. For an existing home, price the immediate repairs and any changes you would want. Bring both totals to the same conversation so a lower starting number does not hide a larger project.')+
 section('Test the routes that matter to you', 'Make separate trips from a possible Westfield address to work, errands, and any regular sports commitments. Drive them when you would normally go. If a house suits your budget but the trip does not suit your schedule, broaden the search before you compromise on the routine.')+
 section('Grand Park, downtown, and time outside', 'Use <a href="https://grandpark.org/">Grand Park’s official site</a> to check the campus and event information for your visit. Then spend time downtown and use the <a href="https://www.westfieldin.gov/">City of Westfield’s parks and trail information</a> to plan a route you would use away from the campus. Treat these as separate stops when comparing locations (sources checked November 18, 2026).')+
 section('Verify enrollment for the property', 'Check the address and current enrollment process with <a href="https://www.wws.k12.in.us/">Westfield Washington Schools</a>; use the district’s own information rather than assuming an assignment from a listing (checked November 18, 2026).')+
 section('Plan for timing as well as repairs', 'With a builder, ask how selections, walkthroughs, and changes to the delivery schedule are handled. With an existing Westfield home, decide which projects must happen before you move in and which can wait. I help turn those questions into a practical list for the consult.')+cta(),card='areas')
page('/areas/fishers/', 'Living in Fishers, Indiana: Fishers District and downtown | Nick Giulioni', 'Compare Fishers District and downtown Fishers, then weigh home condition, travel routes and your everyday routine before buying.', 'Living in Fishers, Indiana',
 section('Which version of your day are you buying?', 'If Fishers District is where you expect to spend an evening, visit it before touring nearby homes. If downtown Fishers and the Nickel Plate Trail draw you in, begin there instead. If walking from home is essential, skip properties until you have checked the actual route rather than treating a Fishers mailing address as a promise.')+
 section('Choose a layout for the way you live', 'In a Fishers home search, compare the spaces you will use every day: entry, kitchen, workspace, and outdoor area. For an existing house, ask whether a proposed change is a simple finish update or a layout project. For a new home, compare the selected plan and lot with the final specification, not only the model you toured.')+
 section('Try both the daily drive and the evening trip', 'Route your workday from each Fishers neighborhood on the shortlist, then try the trip to your preferred evening stop. Check where you would park or cross on foot. Keep those trips in your comparison even when two homes look similar on paper.')+
 section('Downtown Fishers, Fishers District, and the trail', 'Visit downtown Fishers and Fishers District as distinct destinations. The city’s Nickel Plate Trail guide describes connections between neighborhoods, commercial areas, and the downtown Nickel Plate District. Use the route to plan a walk, then check how a particular home connects to it. <a href="https://fishersin.gov/nickel-plate-trail/">Source: City of Fishers trail guide, checked November 18, 2026</a>.')+
 section('Look up the assigned district', 'For a home in Fishers, start with <a href="https://www.hseschools.org/">Hamilton Southeastern’s official district site</a> and verify the property’s district boundary and enrollment details directly (checked November 18, 2026).')+
 section('Separate location from project scope', 'Liking the neighborhood does not settle what a house needs. We can list the work you see, the questions for an inspector, and the improvements you might defer. If the home is being built, ask how the warranty and unfinished items will be handled after handover.')+cta(),card='areas')
page('/about/', 'About Nick Giulioni | Indiana real estate broker, T&H Realty Services', 'Meet Nick Giulioni, a Carmel-based Indiana broker with investing and renovation experience serving buyers and sellers.', 'An agent with an investor’s eye.',section('Who I help','I help buyers and sellers in Carmel, Westfield, and Fishers think through their next move, including homes that need work and owners deciding whether to sell or keep a property.')+section('From tech sales to Indiana homes','My background is in tech sales leadership. I have been investing in Central Indiana since 2017, with '+STAT+'. Years running renovation and new-build work taught me to ask what sits behind a finish and what a project might require. I live in Carmel and am newly licensed as an Indiana real estate broker.')+section('The podcast',POD+' <a href="https://indyreiwiththrealty.podbean.com/">Listen to the show</a>.')+section('My brokerage','I am affiliated with T&amp;H Realty Services.')+section('Careful numbers','I build and use Central Indiana market data through <a href="https://ballpark.build">Ballpark</a> to support careful numbers and better questions about a property. Estimates are a starting point for a conversation, not an appraisal.')+cta(),card='about')
page('/contact/', 'Request a consult | Nick Giulioni', 'Request a buyer, seller or sell-versus-rent consult with Nick Giulioni in Central Indiana.', 'Request a consult.', '<p class="page-deck">Tell me what you are considering. We can work out the next step together.</p>'+form('contact')+'<div class="contact-line"><a href="'+S['phone_tel']+'">'+S['phone_display']+'</a><a href="mailto:'+S['email']+'">'+S['email']+'</a></div><p>I respond personally, usually the same day.</p>')
page('/contact/thanks/', 'Thank you | Nick Giulioni', 'Your consult request has been received.', 'Thanks. I will reply personally, usually the same day.', '<p><a href="/">Back home</a></p>',noindex=True)
page('/contact/error/', 'Request not sent | Nick Giulioni', 'Contact Nick directly if your consult request could not be sent.', 'That did not go through.', '<p>Please email <a href="mailto:'+S['email']+'">'+S['email']+'</a> or call <a href="'+S['phone_tel']+'">'+S['phone_display']+'</a>.</p><p><a href="/">Back home</a></p>',noindex=True)
page('/privacy/', 'Privacy | Nick Giulioni', 'How Nick Giulioni uses and protects information submitted through the consult form.', 'Privacy', section('Your request','Effective November 18, 2026. The form collects your name, email, phone, city or address, intent, message, and consent, along with the page source and receipt time. I use this information to reply to your consult request. The email notification is the stored record for now.')+section('Contact and consent','Your consent covers calls, emails, and texts from Nick about your request. Message and data rates may apply. Reply STOP to opt out of texts. Consent is only for responding to this request; it does not enroll you in a campaign. You can also contact me directly by email or phone.')+section('Processing and deletion','Vercel provides hosting for the site and processes submissions. Resend processes the email notification, and the Quo text service processes the text notification. Your data is not sold or shared for marketing. To request deletion, email <a href="mailto:'+S['email']+'">'+S['email']+'</a>.'))
page('/podcast/', 'Podcast and earlier media | Nick Giulioni', 'The Indy Real Estate Investing Podcast and earlier real estate conversations with Nick Giulioni.', 'Podcast', '<p class="page-deck">'+POD+'</p><p><a href="https://indyreiwiththrealty.podbean.com/">Listen to the show</a></p><section class="editorial"><h2>Earlier media</h2><div class="media-entries">'+MEDIA+'</div></section>'+cta(),card='podcast')
page('/404.html', 'Page not found | Nick Giulioni', 'Find your way back to Nick Giulioni’s Central Indiana real estate site.', 'This page has moved.', '<p>Try <a href="/">home</a>, <a href="/sell/">selling</a>, <a href="/buy/">buying</a>, or <a href="/contact/">request a consult</a>.</p>',noindex=True)
